/* Lift platform carried by an animated driver moby: follows the driver's joint 0, waits at an end (3/5) for the
 * hero to step on, then plays the driver's up or down animation (2/4) with its loop sound until it ends. */
void FUN_L02_002e2228(struct Moby *moby) {
    char *data = (char *)moby->pvars;
    struct Moby *driver = &D_L02_0015FFD8[*(int *)(data + 0xA0)];
    Vec4 delta;
    Vec4 old_rot;
    float joint_mtx[16];
    Vec4 pos;
    int ride;
    int voice;

    scale_vector(&delta, &moby->pos, -1.0f);
    qcopy(&old_rot, &moby->rot);
    FUN_L00_0024f7c8(driver, 0, &pos);
    qcopy(&moby->pos, &pos);
    switch (moby->state) {
    case 0:
        FUN_0020cca8(driver, 0, joint_mtx);
        moby->rot.z = atan2_e2228(joint_mtx[0], joint_mtx[1]);
        moby->state = 1;
        blend_moby_animation(driver, 3, 0, 0);
        break;
    case 1:
        if (D_0014C050[current_level_index][moby->unkB0] == 0xFF) {
            moby->state = 5;
        }
        break;
    case 3:
    case 5:
        ride = 0;
        if (hero.unk2FC == moby && hero.unk30E.s == 0 && moby->unkBC == 0) {
            ride = 1;
        } else if (distance_xyz(&moby->pos, &hero.motion.pos) < 16.0f) {
            if (moby->state == 5 && hero.motion.pos.f[2] < moby->pos.z - 5.0f) {
                ride = 1;
            } else if (moby->state == 3 && moby->pos.z + 5.0f < hero.motion.pos.f[2]) {
                ride = 1;
            }
        }
        if (ride) {
            if (moby->state == 5 || moby->state == 1) {
                moby->state = 2;
                FUN_00212ed8(driver, 0, 0);
                *(int *)(data + 0xA4) = allocate_voice_for_target(2, 4, driver);
            } else {
                moby->state = 4;
                FUN_00212ed8(driver, 2, 0);
                *(int *)(data + 0xA4) = allocate_voice_for_target(0, 4, driver);
            }
        } else if (hero.unk2FC != moby) {
            moby->unkBC = 0;
        }
        break;
    case 2:
    case 4:
        FUN_0020cca8(driver, 0, joint_mtx);
        moby->rot.z = atan2_e2228(joint_mtx[0], joint_mtx[1]);
        if (distance_xyz(&moby->pos, &hero.motion.pos) < 1.5f && hero.motion.pos.f[2] < moby->pos.z - 1.5f) {
            driver->unk58 = 0.0f;
            voice = *(int *)(data + 0xA4);
            if (voice != -1) {
                char *e = D_0013E550 + voice * 0x70;
                if (*(struct Moby **)(e + 0x88) == driver && *(unsigned char *)(e + 0x74) != 0) {
                    release_voice_slot(voice);
                }
            }
            *(int *)(data + 0xA4) = -1;
        }
        if (driver->unk58 == 0.0f &&
            (distance_xyz(&moby->pos, &hero.motion.pos) > 2.0f || moby->pos.z - 1.25f < hero.motion.pos.f[2])) {
            driver->unk58 = 1.0f;
            if (moby->state == 2) {
                *(int *)(data + 0xA4) = allocate_voice_for_target(2, 4, driver);
            } else {
                *(int *)(data + 0xA4) = allocate_voice_for_target(0, 4, driver);
            }
        }
        if (driver->unk70 & 2) {
            voice = *(int *)(data + 0xA4);
            if (voice != -1) {
                char *e = D_0013E550 + voice * 0x70;
                if (*(struct Moby **)(e + 0x88) == driver && *(unsigned char *)(e + 0x74) != 0) {
                    release_voice_slot(voice);
                }
            }
            *(int *)(data + 0xA4) = -1;
            if (moby->state == 2) {
                moby->state = 3;
                blend_moby_animation(driver, 1, 0, 0);
                allocate_voice_for_target(3, 0, driver);
            } else {
                moby->state = 5;
                blend_moby_animation(driver, 3, 0, 0);
                allocate_voice_for_target(1, 0, driver);
            }
            moby->unkBC = 1;
        }
        break;
    case 6:
        break;
    }
    add_vectors(&delta, &delta, &moby->pos);
    FUN_L00_00260738(data + 0x60, &delta, &old_rot, &moby->rot);
}

